      crushedGlue: 'You stood on the glue: closing pulled the stone opposite onto your square and crushed you. Back to the start.', 'pre.lean': 'Lean',
      'vol.1': 'Book One', 'vol.2': 'Book Two', 'chHead.1': 'Chapter 1 · Fold', 'chHead.2': 'Chapter 2 · Stand', 'chHead.3': 'Chapter 3 · Shadow', 'chHead.4': 'Chapter 4 · Banks', 'chHead.5': 'Chapter 5 · Glue', 'chHead.dark': 'Hidden letters',
